INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','relative-clauses','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"relative-clauses","title":"Defining and non-defining relative clauses","level":"B1","order":49,"summary":"Identify a person or thing precisely, or add extra information without changing who you mean.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Defining information","Extra information","Possession and place","When omission is possible"],"rules":[{"title":"Defining information","explanation":"A defining relative clause tells us which person or thing is meant and usually has no surrounding commas. Who refers to people; which refers to things; that can often refer to either in defining clauses. The relative pronoun can be subject or object within its clause.","pattern":"The person **who called** left a message.","commonMistakes":["Do not mark that as wrong where it is a valid defining relative alternative to who or which."],"examples":["Choose a person-relative pronoun: “The assistant **who** prepares the visitor guide is here.”","Choose a person-relative pronoun: “The assistant **who** restores the old portrait is here.”"],"skill":"form"},{"title":"Extra information","explanation":"A non-defining relative clause adds information about an already identified referent and is set off with commas. Use who or which, not that. The relative pronoun is not omitted in this type of clause.","pattern":"My bicycle, **which is red**, is outside.","commonMistakes":["Leaving out the commas may change whether the information identifies the referent or merely adds a detail."],"examples":["Add extra information: “Our assistant, **who** prepares the visitor guide every week, is away.”","Add extra information: “Our assistant, **who** restores the old portrait every week, is away.”"],"skill":"meaning"},{"title":"Possession and place","explanation":"Whose marks a possessive relationship and comes before a noun. Where introduces a relative clause about a place when that place has an adverbial role. Compare the place where we met with the place which we visited: visited takes a direct object.","pattern":"The artist **whose work** won is here.","commonMistakes":["Where is not a universal substitute for which after a place noun; the role inside the clause matters."],"examples":["Express possession: “The assistant **whose** job is to prepare the visitor guide has arrived.”","Express possession: “The assistant **whose** job is to restore the old portrait has arrived.”"],"skill":"contrast"},{"title":"When omission is possible","explanation":"In a defining clause, an object relative pronoun can often be omitted. A subject relative pronoun cannot normally be omitted. Non-defining clauses keep the pronoun regardless of its role.","pattern":"The book **(that) I read** was short. / The book **that won** was long.","commonMistakes":["The person works here without a relative pronoun is a main clause, not a defining clause attached to another noun phrase."],"examples":["In “The task that we chose was to prepare the visitor guide”, what is true about “that”? → **It can be omitted because it is the object in a defining clause.**","In “The task that we chose was to restore the old portrait”, what is true about “that”? → **It can be omitted because it is the object in a defining clause.**"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-relative","bc-nondefining"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"1e35dfa0-2a8a-514a-abbe-bff2637d163f","topicSlug":"relative-clauses","level":"B1","prompt":"Choose a person-relative pronoun: “The assistant ____ prepares the visitor guide is here.”","choices":[{"id":"A","text":"which"},{"id":"B","text":"whose"},{"id":"C","text":"where"},{"id":"D","text":"who"}],"answerId":"D","hint":"Identify the antecedent as a **person** and the gap as the clause’s subject.","explanation":"**Who** refers to the person and is the subject of the relative clause.","keywords":["relative-person"],"skill":"relative-person","contextKey":"relative-clauses-1","fingerprint":"a8dd12d940de259e9d935e05cc06bfe0dc691a8dd175d2582692e721b6c16556","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-relative"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Identify the antecedent as a **person** and the gap as the clause’s subject.","**Who** refers to the person and is the subject of the relative clause.","Choose **who**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Which normally refers to things, not this person.","B":"Whose needs a following noun to express possession.","C":"Where would express a place role, not the person subject.","D":"**Who** refers to the person and is the subject of the relative clause."}}},{"id":"a8c9cf21-b15e-525e-a144-a8e09f93d73e","topicSlug":"relative-clauses","level":"B1","prompt":"Add extra information: “Our assistant, ____ prepares the visitor guide every week, is away.”","choices":[{"id":"A","text":"who"},{"id":"B","text":"that"},{"id":"C","text":"—"},{"id":"D","text":"whose"}],"answerId":"A","hint":"The **commas** signal extra information, and the referent is a person.","explanation":"The commas mark a non-defining clause about a person, so use **who**.","keywords":["nondefining-relative"],"skill":"nondefining-relative","contextKey":"relative-clauses-1","fingerprint":"2d42689761113b48069d5974c9537c38ab95d12fa48f418c5faa397f33fca6b5","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-relative"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The **commas** signal extra information, and the referent is a person.","The commas mark a non-defining clause about a person, so use **who**.","Choose **who**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The commas mark a non-defining clause about a person, so use **who**.","B":"That is not used as the relative pronoun in an ordinary non-defining clause.","C":"The pronoun cannot be omitted in a non-defining clause.","D":"Whose requires a noun after it to express possession."}}},{"id":"cf1f0486-e878-5c65-adf4-6cef95ac204d","topicSlug":"relative-clauses","level":"B1","prompt":"Express possession: “The assistant ____ job is to prepare the visitor guide has arrived.”","choices":[{"id":"A","text":"who’s"},{"id":"B","text":"which"},{"id":"C","text":"whose"},{"id":"D","text":"who"}],"answerId":"C","hint":"The blank comes before **job** and means **the assistant’s**.","explanation":"**Whose job** marks the job’s relationship to the assistant.","keywords":["relative-possession"],"skill":"relative-possession","contextKey":"relative-clauses-1","fingerprint":"e3e920e59ef56bfa0ffd5fd722febfcfcc1c7b5f3ad5edf8976509d2d379e8a1","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-relative"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The blank comes before **job** and means **the assistant’s**.","**Whose job** marks the job’s relationship to the assistant.","Choose **whose**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Who’s means who is or who has, not whose.","B":"Which job would ask or identify a job, not mark the assistant’s possession here.","C":"**Whose job** marks the job’s relationship to the assistant.","D":"Who alone cannot mark possession before job."}}},{"id":"3f36fcd8-e7c3-5e6a-a017-f58385f2d44b","topicSlug":"relative-clauses","level":"B1","prompt":"In “The task that we chose was to prepare the visitor guide”, what is true about “that”?","choices":[{"id":"A","text":"It must change to whose because task is a noun."},{"id":"B","text":"It can be omitted because it is the object in a defining clause."},{"id":"C","text":"It must stay because every relative pronoun is a subject."},{"id":"D","text":"It can be omitted because all non-defining pronouns can be omitted."}],"answerId":"B","hint":"Inside **we chose**, locate the subject and the missing object.","explanation":"We is the subject and that represents the object of chose; a defining object relative can be omitted.","keywords":["object-relative-omission"],"skill":"object-relative-omission","contextKey":"relative-clauses-1","fingerprint":"85e4dc88b393fe176694f80019f824958773887e5ebce460b8806aefc4ecb131","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-relative"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Inside **we chose**, locate the subject and the missing object.","We is the subject and that represents the object of chose; a defining object relative can be omitted.","Choose **It can be omitted because it is the object in a defining clause.**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Whose would mark possession, which is not the role here.","B":"We is the subject and that represents the object of chose; a defining object relative can be omitted.","C":"Relative pronouns can be objects; here we is the subject.","D":"This is defining, and non-defining relative pronouns cannot normally be omitted."}}},{"id":"9993a141-c0a7-5971-a481-9818fc44e719","topicSlug":"relative-clauses","level":"B1","prompt":"Choose a person-relative pronoun: “The assistant ____ restores the old portrait is here.”","choices":[{"id":"A","text":"where"},{"id":"B","text":"who"},{"id":"C","text":"which"},{"id":"D","text":"whose"}],"answerId":"B","hint":"Identify the antecedent as a **person** and the gap as the clause’s subject.","explanation":"**Who** refers to the person and is the subject of the relative clause.","keywords":["relative-person"],"skill":"relative-person","contextKey":"relative-clauses-2","fingerprint":"4e0d062867e60e382ea23352d04a2b52e030423db5a7671412739043fc574da3","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-relative"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Identify the antecedent as a **person** and the gap as the clause’s subject.","**Who** refers to the person and is the subject of the relative clause.","Choose **who**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Where would express a place role, not the person subject.","B":"**Who** refers to the person and is the subject of the relative clause.","C":"Which normally refers to things, not this person.","D":"Whose needs a following noun to express possession."}}},{"id":"e0f006f7-f4e9-52c6-a807-bfdf64a796a7","topicSlug":"relative-clauses","level":"B1","prompt":"Add extra information: “Our assistant, ____ restores the old portrait every week, is away.”","choices":[{"id":"A","text":"who"},{"id":"B","text":"that"},{"id":"C","text":"—"},{"id":"D","text":"whose"}],"answerId":"A","hint":"The **commas** signal extra information, and the referent is a person.","explanation":"The commas mark a non-defining clause about a person, so use **who**.","keywords":["nondefining-relative"],"skill":"nondefining-relative","contextKey":"relative-clauses-2","fingerprint":"ff51e9efa0ed671d7b9cc3c84203b06abc0b817fa7bb2bfc37187d3d9ee2ce84","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-relative"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-re